using System.Reflection;
using RoguePrince.CheatMenu;
using RoguePrince.CheatMenu.Core;
using UnityEngine;
int passed=0,failed=0;
void Check(string name,Action test){try{test();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+(e.InnerException??e).Message);}}
void Assert(bool ok){if(!ok)throw new Exception("assertion failed");}
const BindingFlags flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
var type=typeof(GameSession).Assembly.GetType("RoguePrince.CheatMenu.FrameObservationActions");
Check("production native gameplay frame observer exists",()=>Assert(type!=null));
if(type==null){Console.WriteLine($"{passed} passed / {failed} failed");return 1;}
GameSession game=null;GameplayUpdate owner=null;GameStateStack stack=null;object actions=null;bool menuShown=false;
object Call(string method,params object[] args)=>type.GetMethod(method,flags).Invoke(actions,args);
T Read<T>(string property)=>(T)type.GetProperty(property,flags).GetValue(actions);
void Reject(Action work){bool rejected=false;try{work();}catch{rejected=true;}Assert(rejected);}
void Setup(){menuShown=false;Time.frameCount=100;Time.timeScale=1;Time.deltaTime=.017f;Time.realtimeSinceStartup=20;Application.isFocused=true;TrainingActions.Scope=new(1,1,3,4,0,0);owner=new();game=new();game.Player.context=owner._systemManager._context;stack=new();stack.stack.Add(owner);UnityEngine.Object.Stacks=new[]{stack};actions=Activator.CreateInstance(type,flags,null,new object[]{game},null);type.GetField("IsMenuVisible",flags)?.SetValue(actions,(Func<bool>)(()=>menuShown));type.GetField("Available",flags).SetValue(null,true);Plugin.Events.Clear();}
void Enable()=>Call("Enable",(Action)(()=>{}));
bool Prefix(string phase,GameplayUpdate who=null){who??=owner;var hook=type.Assembly.GetType("RoguePrince.CheatMenu.FrameObservation"+phase+"Patch");object[] args={who,false};bool result=(bool)hook.GetMethod("Prefix",flags).Invoke(null,args);if(result){if(phase=="Update")who.OnUpdate();else if(phase=="Fixed")who.OnFixedUpdate();else who.OnLateUpdate();hook.GetMethod("Postfix",flags).Invoke(null,new object[]{who,args[1]});}return result;}
void Step()=>Call("Step",(Action)(()=>{}));
void Next(){Time.frameCount++;Time.realtimeSinceStartup+=.02f;}
void Complete(){Next();Assert(Prefix("Fixed"));Assert(Prefix("Update"));Assert(Prefix("Late"));}
Check("entry pauses time and gates all three native phases",()=>{Setup();Enable();Assert(Read<bool>("Enabled")&&Time.timeScale==0);foreach(var phase in new[]{"Fixed","Update","Late"})Assert(!Prefix(phase));});
Check("disabled hook passes through",()=>{Setup();foreach(var phase in new[]{"Fixed","Update","Late"})Assert(Prefix(phase));});
Check("one request admits only next Unity frame and returns to pause",()=>{Setup();Enable();Step();Assert(!Prefix("Update"));Complete();Assert(Time.timeScale==0&&!Read<bool>("Pending")&&Read<int>("Completed")==1);Next();Assert(!Prefix("Update"));});
Check("completed status records observed U F L and measured delta",()=>{Setup();Enable();Step();Complete();var s=Read<string>("Status");Assert(s.Contains("1 / 1 / 1")&&s.Contains("17"));Assert(Plugin.Events.Any(x=>x.Contains("frame_observation_complete")&&x.Contains("update=1")&&x.Contains("fixed=1")&&x.Contains("late=1")));});
Check("zero fixed calls is reported rather than manufactured",()=>{Setup();Enable();Step();Next();Assert(Prefix("Update")&&Prefix("Late"));Assert(Read<string>("Status").Contains("1 / 0 / 1"));});
Check("multiple fixed calls remain native and are visible",()=>{Setup();Enable();Step();Next();Assert(Prefix("Fixed")&&Prefix("Fixed")&&Prefix("Update")&&Prefix("Late"));Assert(Read<string>("Status").Contains("1 / 2 / 1"));});
Check("repeat requests are rejected until completion",()=>{Setup();Enable();Step();Reject(Step);Assert(Read<bool>("Pending"));Complete();Step();Complete();Assert(Read<int>("Completed")==2);});
Check("duplicate Update in same frame is stopped",()=>{Setup();Enable();Step();Next();Assert(Prefix("Update")&&!Prefix("Update")&&Prefix("Late"));Assert(Read<int>("Completed")==1);});
Check("Late before Update cannot claim completion",()=>{Setup();Enable();Step();Next();Assert(!Prefix("Late"));Call("Tick",false);Next();Call("Tick",false);Assert(Read<int>("Completed")==0&&Read<bool>("Error")&&Time.timeScale==0);});
Check("missing native Late aborts on next frame",()=>{Setup();Enable();Step();Next();Prefix("Update");Next();Call("Tick",false);Assert(!Read<bool>("Pending")&&Read<bool>("Enabled")&&Read<bool>("Error")&&Time.timeScale==0);});
Check("real-time watchdog aborts before another admission",()=>{Setup();Enable();Step();Time.realtimeSinceStartup+=2;Assert(!Prefix("Update"));Assert(Time.timeScale==0&&!Read<bool>("Pending"));});
Check("opening menu cancels pending step",()=>{Setup();Enable();Step();Call("Tick",true);Assert(!Read<bool>("Pending")&&Time.timeScale==0&&Read<int>("Completed")==0);});
Check("foreign GameplayUpdate is never gated or credited",()=>{Setup();Enable();var foreign=new GameplayUpdate();Assert(Prefix("Update",foreign)&&Read<int>("Completed")==0);});
foreach(var nativePause in new[]{false,true})Check("restore captured speed nativePause="+nativePause,()=>{Setup();Time.timeScale=.5f;Enable();owner._systemManager._context.Paused=nativePause;Call("Restore");Assert(!Read<bool>("Enabled")&&Time.timeScale==(nativePause?0:.5f));Assert(owner._systemManager._context.Paused==nativePause);});
Check("restore preserves a foreign timeScale write",()=>{Setup();Enable();Time.timeScale=.3f;Call("Restore");Assert(Time.timeScale==.3f);});
Check("step restores captured non-unit speed and final pause",()=>{Setup();Time.timeScale=.5f;Enable();Step();Assert(Time.timeScale==.5f);Complete();Call("Restore");Assert(Time.timeScale==.5f);});
foreach(var change in new[]{"room","scene","generation","player","loading","focus","manager","context","inactive","popped","pause"})Check("scope loss releases only captured ownership: "+change,()=>{Setup();Enable();switch(change){case "room":TrainingActions.Scope=new(1,1,3,5,0,0);break;case "scene":TrainingActions.Scope=new(1,1,4,4,0,0);break;case "generation":TrainingActions.Scope=new(2,1,3,4,0,0);break;case "player":game.Player=new(){context=new()};break;case "loading":game.Ready=false;break;case "focus":Application.isFocused=false;break;case "manager":owner._systemManager=new();break;case "context":owner._systemManager._context=new();break;case "inactive":owner.isActive=false;break;case "popped":owner.isPushed=false;break;case "pause":owner._systemManager._context.Paused=true;break;}Call("Tick",false);Assert(!Read<bool>("Enabled")&&Read<int>("Completed")==0);Assert(Time.timeScale==(change=="pause"?0:1));});
foreach(var bad in new[]{"patch","no owner","two owners","two stacks","context","paused","time zero","nan","focus","scope"})Check("reject unsafe entry: "+bad,()=>{Setup();switch(bad){case "patch":type.GetField("Available",flags).SetValue(null,false);break;case "no owner":stack.stack.Clear();break;case "two owners":stack.stack.Add(new GameplayUpdate{_systemManager=owner._systemManager});break;case "two stacks":UnityEngine.Object.Stacks=new[]{stack,stack};break;case "context":game.Player.context=new();break;case "paused":owner._systemManager._context.Paused=true;break;case "time zero":Time.timeScale=0;break;case "nan":Time.timeScale=float.NaN;break;case "focus":Application.isFocused=false;break;case "scope":game.Ready=false;break;}Reject(Enable);Assert(!Read<bool>("Enabled"));});
Check("release callback invalidating scope cannot acquire",()=>{Setup();Reject(()=>Call("Enable",(Action)(()=>game.Ready=false)));Assert(!Read<bool>("Enabled")&&Time.timeScale==1);});
Check("step callback invalidating owner cannot unpause",()=>{Setup();Enable();Reject(()=>Call("Step",(Action)(()=>owner.isActive=false)));Assert(!Read<bool>("Enabled")&&Time.timeScale==1);});
Check("native context pause during step is preserved",()=>{Setup();Enable();Step();Next();owner._systemManager._context.Paused=true;Assert(Prefix("Update"));Assert(!Read<bool>("Enabled")&&Time.timeScale==0&&Read<int>("Completed")==0);});
Check("restore is idempotent before after and during step",()=>{Setup();Call("Restore");Enable();Step();Call("Restore");Call("Restore");Assert(!Read<bool>("Enabled")&&!Read<bool>("Pending")&&Time.timeScale==1);});
Check("original dispatch body runs only once for completed request",()=>{Setup();Enable();Prefix("Update");Step();Complete();Next();Prefix("Update");Prefix("Late");Assert(owner.Updates==1&&owner.Fixed==1&&owner.Late==1);});
Check("native binding change during original Update cannot confirm",()=>{Setup();Enable();Step();Next();owner.DuringUpdate=()=>owner._systemManager=new();Prefix("Update");Assert(!Read<bool>("Enabled")&&Read<int>("Completed")==0&&Time.timeScale==1);});
Check("native pause during original Late cannot confirm",()=>{Setup();Enable();Step();Next();Prefix("Update");owner.DuringLate=()=>owner._systemManager._context.Paused=true;Prefix("Late");Assert(!Read<bool>("Enabled")&&Read<int>("Completed")==0&&Time.timeScale==0);});
foreach(var delta in new[]{0f,-1f,float.NaN,float.PositiveInfinity})Check("invalid observed delta cannot claim frame: "+delta,()=>{Setup();Enable();Step();Next();Prefix("Update");Time.deltaTime=delta;Prefix("Late");Assert(Read<int>("Completed")==0&&Read<bool>("Error")&&Time.timeScale==0);});
Check("native time writer during step supplies resume value",()=>{Setup();Enable();Step();Next();owner.DuringUpdate=()=>Time.timeScale=.25f;Prefix("Update");Prefix("Late");Call("Restore");Assert(Time.timeScale==.25f);});
Check("native pause resume chain eventually releases observation time lease",()=>{Setup();Enable();owner._systemManager._context.Paused=true;Call("Tick",false);Assert(!Read<bool>("Enabled")&&Time.timeScale==0);owner._systemManager._context.Paused=false;Call("Tick",false);Assert(Time.timeScale==1&&!Read<bool>("RecoveryPending"));});
Check("deferred release waits for menu to close",()=>{Setup();Enable();owner._systemManager._context.Paused=true;Call("Restore");owner._systemManager._context.Paused=false;Call("Tick",true);Assert(Time.timeScale==0&&Read<bool>("RecoveryPending"));Call("Tick",false);Assert(Time.timeScale==1&&!Read<bool>("RecoveryPending"));});
Check("deferred release preserves a foreign positive time write",()=>{Setup();Enable();owner._systemManager._context.Paused=true;Call("Restore");Time.timeScale=.3f;Call("Tick",false);Assert(Time.timeScale==.3f&&!Read<bool>("RecoveryPending"));});
Check("deferred release rejects a second observation lease",()=>{Setup();Enable();owner._systemManager._context.Paused=true;Call("Restore");Reject(Enable);Assert(Read<bool>("RecoveryPending"));});
Check("deferred release survives repeated manual restore calls",()=>{Setup();Enable();owner._systemManager._context.Paused=true;Call("Restore");Call("Restore");Assert(Read<bool>("RecoveryPending")&&Time.timeScale==0);owner._systemManager._context.Paused=false;Call("Restore");Assert(!Read<bool>("RecoveryPending")&&Time.timeScale==1);});
Check("deferred scope replacement releases after new owner ready",()=>{Setup();Enable();owner._systemManager._context.Paused=true;Call("Restore");game.Ready=false;game.Player=new(){context=new()};Call("Tick",false);Assert(Time.timeScale==0&&Read<bool>("RecoveryPending"));game.Ready=true;TrainingActions.Scope=new(2,2,4,5,0,0);Call("Tick",false);Assert(Time.timeScale==1&&!Read<bool>("RecoveryPending"));});
Check("deferred native replacement pause is preserved until resumed",()=>{Setup();Enable();owner._systemManager._context.Paused=true;Call("Restore");game.Player=new(){context=new(){Paused=true}};TrainingActions.Scope=new(2,2,4,5,0,0);Call("Tick",false);Assert(Time.timeScale==0&&Read<bool>("RecoveryPending"));game.Player.context.Paused=false;Call("Tick",false);Assert(Time.timeScale==1&&!Read<bool>("RecoveryPending"));});
Check("menu restore cannot bypass menu pause lease",()=>{Setup();Enable();owner._systemManager._context.Paused=true;Call("Restore");menuShown=true;owner._systemManager._context.Paused=false;Call("Restore");Assert(Time.timeScale==0&&Read<bool>("RecoveryPending"));menuShown=false;Call("Tick",false);Assert(Time.timeScale==1&&!Read<bool>("RecoveryPending"));});
Check("direct initial restore from visible menu retains cleanup until hidden",()=>{Setup();Enable();menuShown=true;Call("Restore");Assert(!Read<bool>("Enabled")&&Read<bool>("RecoveryPending")&&Time.timeScale==0);menuShown=false;Call("Tick",false);Assert(Time.timeScale==1);});
foreach(var replaceManager in new[]{false,true})Check("same player replacement context supersedes retained paused manager: "+replaceManager,()=>{Setup();Enable();owner._systemManager._context.Paused=true;Call("Restore");game.Player.context=new();if(replaceManager)owner._systemManager=new(){_context=game.Player.context};Call("Tick",false);Assert(!Read<bool>("RecoveryPending")&&Time.timeScale==1);});
Console.WriteLine($"RESULT {passed} passed, {failed} failed");return failed==0?0:1;
